import attr
from attr.validators import min_len
import pytest

def test_min_len_valid():
    @attr.s
    class Tester:
        value = attr.ib(validator=min_len(4))

    Tester("1234")
    Tester([1, 2, 3, 4])
    Tester("abcde")

def test_min_len_invalid():
    @attr.s
    class Tester:
        value = attr.ib(validator=min_len(4))

    with pytest.raises(ValueError) as e:
        Tester("123")
    assert "Length of 'value' must be >= 4: 3" in str(e.value)

def test_min_len_repr():
    assert repr(min_len(4)) == "<min_len validator for 4>"

if __name__ == "__main__":
    test_min_len_valid()
    test_min_len_invalid()
    test_min_len_repr()
    print("All tests passed!")

